        /// ```
        /// use libgit2_crustify::libgit2::deps::llhttp::api::Settings;
        ///
        /// let settings = Settings::new();
        /// assert!(settings.as_ref().on_body().is_none());
        /// assert!(settings.as_ref().on_message_complete().is_none());
        /// ```
